for f in sorted(glob.glob('*.messages.json')):
    tid=f.replace('.messages.json','')
    m=json.load(open(f))
    cmds=[]
    for msg in m:
        if msg.get('role')=='assistant' and msg.get('tool_calls'):
            for t in msg['tool_calls']:
                cmds.append(t.get('function',{}).get('arguments',''))
    # find max run of identical consecutive commands
    maxrun=1;cur=1;runcmd=''
    for i in range(1,len(cmds)):
        if cmds[i]==cmds[i-1]:
            cur+=1
            if cur>maxrun: maxrun=cur; runcmd=cmds[i]
        else: cur=1
    # also count near-dup: total cmds vs unique
    uniq=len(set(cmds))
    tot=len(cmds)
    if maxrun>=3 or (tot>=15 and uniq<tot*0.5):
        print(tid, 'maxrun=%d'%maxrun, 'tot=%d uniq=%d'%(tot,uniq))
"

